def solve(coins, amount):
    try:
        amt = int(amount)
    except Exception:
        return -1
    if amt < 0:
        return -1
    if amt == 0:
        return 0
    try:
        vals = [int(c) for c in coins]
    except Exception:
        return -1
    vals = [c for c in vals if c > 0]
    if not vals:
        return -1
    INF = amt + 1
    dp = [INF] * (amt + 1)
    dp[0] = 0
    for a in range(1, amt + 1):
        best = INF
        for c in vals:
            if c <= a and dp[a - c] + 1 < best:
                best = dp[a - c] + 1
        dp[a] = best
    return dp[amt] if dp[amt] != INF else -1

